{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")

    nodes = case.get("nodes")
    core = case.get("core_distance")
    distances = case.get("distances")

    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if any(not isinstance(node, str) for node in nodes):
        raise ValueError("node identifiers must be strings")
    if len(set(nodes)) != len(nodes):
        raise ValueError("node identifiers must be unique")
    if not isinstance(core, dict) or set(core) != set(nodes):
        raise ValueError("core_distance must contain exactly one value per node")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    def valid_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    for node in nodes:
        if not valid_number(core[node]):
            raise ValueError("core distances must be finite numbers")

    node_set = set(nodes)
    expected_pairs = {tuple(sorted((nodes[i], nodes[j]))) for i in range(len(nodes)) for j in range(i + 1, len(nodes))}
    seen_pairs = set()
    edges = []

    for entry in distances:
        if not isinstance(entry, list) or len(entry) != 3:
            raise ValueError("each distance must be a three-item list")
        left, right, distance = entry
        if not isinstance(left, str) or not isinstance(right, str):
            raise ValueError("distance endpoints must be strings")
        if left not in node_set or right not in node_set or left == right:
            raise ValueError("distance endpoint is invalid")
        if not valid_number(distance):
            raise ValueError("distances must be finite numbers")
        pair = tuple(sorted((left, right)))
        if pair in seen_pairs:
            raise ValueError("duplicate undirected distance")
        seen_pairs.add(pair)
        weight = max(core[left], core[right], distance)
        edges.append((weight, pair[0], pair[1]))

    if seen_pairs != expected_pairs:
        raise ValueError("distance matrix must contain every undirected pair")

    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            return False
        if rank[root_left] < rank[root_right]:
            root_left, root_right = root_right, root_left
        parent[root_right] = root_left
        if rank[root_left] == rank[root_right]:
            rank[root_left] += 1
        return True

    selected = []
    total = 0.0
    for weight, left, right in edges:
        if union(left, right):
            selected.append([left, right, weight])
            total += weight
            if len(selected) == len(nodes) - 1:
                break

    if len(selected) != len(nodes) - 1:
        raise ValueError("distance graph is disconnected")

    return {"mst_edges": selected, "total_weight": total}
